      tb.appendChild(tr);
    });
    tb.querySelectorAll('[data-copy]').forEach((b) => b.onclick = () => { navigator.clipboard.writeText(linkDe(b.dataset.copy)); toast('Link copiado!'); });
    tb.querySelectorAll('[data-rev]').forEach((b) => b.onclick = async () => { await call('acesso_revogar', { linha: +b.dataset.rev }); toast('Acesso revogado'); carregaAcessos(); });
