    const head = d.cabecalho || [];
    $('#t-aba thead').innerHTML = '<tr>' + head.map((h) => `<th>${esc(h)}</th>`).join('') + '</tr>';
    $('#t-aba tbody').innerHTML = (d.linhas || []).map((r) =>
