  }
  $('#f-doc').onsubmit = async (e) => {
    e.preventDefault();
    const fd = new FormData(e.target);
    const file = fd.get('arquivo');
    if (!file || !file.size) return;
    if (file.size > 9 * 1024 * 1024) { toast('Arquivo acima de 9 MB — envie por seções.'); return; }
    $('#btn-doc').disabled = true; $('#btn-doc').textContent = 'Extraindo… (pode levar 1 min)';
