      const b64 = await new Promise((ok) => { const fr = new FileReader(); fr.onload = () => ok(String(fr.result).split(',')[1]); fr.readAsDataURL(file); });
      const r = await call('doc_upload', { obra_id: fd.get('obra_id'), tipo: fd.get('tipo'), titulo: fd.get('titulo'),
        versao: fd.get('versao') || 'v1', mime: file.type || 'application/pdf', data: b64 });
      toast(`Documento salvo: ${r.chars || 0} caracteres extraídos`);
      e.target.reset(); carregaDocs();
    } catch (err) { toast('Falha no envio — tente novamente'); }
    $('#btn-doc').disabled = false; $('#btn-doc').textContent = 'Enviar e extrair';
  };

  carregaFarol();
</script>

